// @ts-nocheck – scaffold generated by scripts/build-manifest.mjs; props mirror the manifest's Figma properties.
// Fill FIGMA_NODE_URL once the kit exists, then run `pnpm figma:connect` to publish.
import figma from '@figma/code-connect';
import { PriceField } from '@davinci-ai/react';

const FIGMA_NODE_URL = 'FIGMA_NODE_URL'; // e.g. https://www.figma.com/design/<file>?node-id=<id>  (Inputs/PriceField)

figma.connect(PriceField, FIGMA_NODE_URL, {
  props: {
    size: figma.enum('size', { 'sm': 'sm', 'md': 'md', 'lg': 'lg' }),
    label: figma.string('label'),
    description: figma.string('description'),
    errorMessage: figma.string('errorMessage'),
    placeholder: figma.string('placeholder'),
    suffix: figma.string('suffix'),
    hideSteppers: figma.boolean('hideSteppers'),
  },
  example: ({ label, size, description, errorMessage, placeholder, suffix, hideSteppers }) => (
    <PriceField size={size} description={description} errorMessage={errorMessage} placeholder={placeholder} suffix={suffix} hideSteppers={hideSteppers}>{label}</PriceField>
  ),
});
